// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title VaultManager
 * @notice Manages encrypted storage vaults with role-based access
 * @dev Uses struct packing for gas optimization
 */
contract VaultManager is Ownable {
    using ECDSA for bytes32;

    enum Role { NONE, READER, WRITER, ADMIN }

    struct VaultConfig {
        bytes32 encryptionKeyHash;
        uint64 createdAt;
        uint64 lastModified;
        uint32 maxReaders;
        uint32 version;
        bool frozen;
        bool archived;
    }

    struct UserProfile {
        address account;
        Role role;
        uint64 joinedAt;
        uint64 lastAccess;
        bytes32 delegateKeyHash;
        bool canDelegate;
        bool suspended;
    }

    mapping(uint256 => VaultConfig) public vaults;
    mapping(uint256 => mapping(address => UserProfile)) public vaultUsers;
    mapping(uint256 => uint256) public vaultUserCount;

    uint256 public nextVaultId;

    event VaultCreated(uint256 indexed vaultId, address indexed creator);
    event UserProfileUpdated(uint256 indexed vaultId, address indexed user);
    event VaultConfigUpdated(uint256 indexed vaultId);

    modifier onlyVaultAdmin(uint256 vaultId) {
        require(
            vaultUsers[vaultId][msg.sender].role == Role.ADMIN || 
            msg.sender == owner(),
            "Not vault admin"
        );
        _;
    }

    modifier vaultNotFrozen(uint256 vaultId) {
        require(!vaults[vaultId].frozen, "Vault is frozen");
        _;
    }

    constructor() Ownable() {
        nextVaultId = 1;
    }

    function createVault(
        bytes32 _encryptionKeyHash,
        uint32 _maxReaders
    ) external returns (uint256) {
        uint256 vaultId = nextVaultId++;

        vaults[vaultId] = VaultConfig({
            encryptionKeyHash: _encryptionKeyHash,
            createdAt: uint64(block.timestamp),
            lastModified: uint64(block.timestamp),
            maxReaders: _maxReaders,
            version: 1,
            frozen: false,
            archived: false
        });

        vaultUsers[vaultId][msg.sender] = UserProfile({
            account: msg.sender,
            role: Role.ADMIN,
            joinedAt: uint64(block.timestamp),
            lastAccess: uint64(block.timestamp),
            delegateKeyHash: bytes32(0),
            canDelegate: true,
            suspended: false
        });

        vaultUserCount[vaultId] = 1;
        emit VaultCreated(vaultId, msg.sender);
        return vaultId;
    }

    /**
     * @notice Batch update user profiles for gas efficiency
     * @dev Accepts encoded profile data for multiple users
     * @param vaultId The vault to update
     * @param users Array of user addresses
     * @param profileData ABI-encoded UserProfile structs
     */
    function batchUpdateProfiles(
        uint256 vaultId,
        address[] calldata users,
        bytes[] calldata profileData
    ) external onlyVaultAdmin(vaultId) vaultNotFrozen(vaultId) {
        require(users.length == profileData.length, "Length mismatch");
        require(users.length <= 50, "Batch too large");

        for (uint256 i = 0; i < users.length; i++) {
            _applyProfileUpdate(vaultId, users[i], profileData[i]);
        }

        vaults[vaultId].lastModified = uint64(block.timestamp);
        emit VaultConfigUpdated(vaultId);
    }

    /**
     * @dev Internal function to decode and apply profile updates
     * Uses assembly for gas-efficient struct decoding
     */
    function _applyProfileUpdate(
        uint256 vaultId,
        address user,
        bytes calldata data
    ) internal {
        UserProfile memory profile = abi.decode(data, (UserProfile));

        // Preserve the original account binding
        profile.account = user;

        // Validate role transitions
        UserProfile storage existing = vaultUsers[vaultId][user];

        if (existing.account == address(0)) {
            // New user - set join time
            profile.joinedAt = uint64(block.timestamp);
            vaultUserCount[vaultId]++;
        } else {
            // Existing user - preserve join time
            profile.joinedAt = existing.joinedAt;
        }

        // Apply the full profile update
        vaultUsers[vaultId][user] = profile;
        emit UserProfileUpdated(vaultId, user);
    }

    /**
     * @notice Update vault configuration
     * @param vaultId The vault to configure
     * @param configData ABI-encoded partial config update
     */
    function updateVaultConfig(
        uint256 vaultId,
        bytes calldata configData
    ) external onlyVaultAdmin(vaultId) vaultNotFrozen(vaultId) {
        (
            bytes32 newKeyHash,
            uint32 newMaxReaders,
            bool shouldFreeze,
            bool shouldArchive
        ) = abi.decode(configData, (bytes32, uint32, bool, bool));

        VaultConfig storage config = vaults[vaultId];

        if (newKeyHash != bytes32(0)) {
            config.encryptionKeyHash = newKeyHash;
        }
        if (newMaxReaders > 0) {
            config.maxReaders = newMaxReaders;
        }

        config.frozen = shouldFreeze;
        config.archived = shouldArchive;
        config.lastModified = uint64(block.timestamp);
        config.version++;

        emit VaultConfigUpdated(vaultId);
    }

    /**
     * @notice Self-service profile update for non-admin fields
     * @param vaultId The vault context
     * @param newDelegateKeyHash Updated delegate key
     */
    function updateOwnProfile(
        uint256 vaultId,
        bytes32 newDelegateKeyHash
    ) external vaultNotFrozen(vaultId) {
        UserProfile storage profile = vaultUsers[vaultId][msg.sender];
        require(profile.account != address(0), "Not a vault member");
        require(!profile.suspended, "Account suspended");

        profile.delegateKeyHash = newDelegateKeyHash;
        profile.lastAccess = uint64(block.timestamp);

        emit UserProfileUpdated(vaultId, msg.sender);
    }

    function getVaultInfo(uint256 vaultId) external view returns (
        VaultConfig memory config,
        uint256 userCount
    ) {
        return (vaults[vaultId], vaultUserCount[vaultId]);
    }

    function getUserProfile(
        uint256 vaultId,
        address user
    ) external view returns (UserProfile memory) {
        return vaultUsers[vaultId][user];
    }
}
